#!/usr/bin/env python3
"""
Скрипт для rebuild NixOS конфигурации.
Заменяет fish-функцию rebuild с поддержкой prehook/posthook.
"""

import argparse
import subprocess
import signal
import sys
import os
from pathlib import Path


class RebuildProcess:
    """Управление процессом rebuild с обработкой прерываний."""

    def __init__(self, args):
        self.args = args
        self.nh_process = None
        self.interrupted = False

    def run_hooks(self, hooks, phase="prehook"):
        """Выполнить список хуков. Возвращает True если все успешны."""
        if not hooks:
            return True

        for hook in hooks:
            hook = hook.strip()
            if not hook:
                continue

            print(f"\n>>> Executing {phase}: {hook}")
            try:
                result = subprocess.run(
                    hook,
                    shell=True,
                    check=True,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT,
                    text=True
                )
                if result.stdout:
                    print(result.stdout, end='')
            except subprocess.CalledProcessError as e:
                if phase == "prehook":
                    print(f"\n!!! {phase} '{hook}' failed with code {e.returncode}, stopping")
                    return False
                else:
                    print(f"\n!!! WARNING: {phase} '{hook}' failed with code {e.returncode}, continuing")
        return True

    def has_changes(self):
        """Проверить наличие изменений в git."""
        try:
            result = subprocess.run(
                ["git", "diff", "--quiet"],
                capture_output=True,
                text=True
            )
            return result.returncode != 0
        except Exception:
            return False

    def commit_changes(self, message):
        """Сделать коммит изменений. Возвращает True если коммит успешен."""
        if self.args.no_commit:
            return False

        if not self.has_changes():
            return False

        try:
            subprocess.run(["git", "add", "."], check=True)
            subprocess.run(["git", "commit", "-m", message], check=True)
            return True
        except subprocess.CalledProcessError:
            return False

    def push_changes(self):
        """Сделать push изменений."""
        if self.args.no_push:
            return False

        try:
            subprocess.run(["git", "push"], check=True)
            return True
        except subprocess.CalledProcessError:
            return False

    def run_rebuild(self):
        """Запустить nh os switch с потоковым выводом."""
        rebuild_status = "FAIL"

        try:
            # Запускаем nh с потоковым выводом
            self.nh_process = subprocess.Popen(
                ["nh", "os", "switch", ".", "--log-format", "bar"],
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1
            )

            # Читаем вывод построчно в реальном времени
            if self.nh_process.stdout:
                for line in self.nh_process.stdout:
                    print(line, end='')
                    sys.stdout.flush()

            # Ждём завершения процесса
            returncode = self.nh_process.wait()
            rebuild_status = "OK" if returncode == 0 else "FAIL"

        except KeyboardInterrupt:
            self.interrupted = True
            if self.nh_process and self.nh_process.poll() is None:
                self.nh_process.terminate()
                try:
                    self.nh_process.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    self.nh_process.kill()
            print("\n!!! Rebuild interrupted by user")
            rebuild_status = "FAIL"
            sys.exit(130)

        return rebuild_status

    def run(self):
        """Основная логика rebuild."""
        # Выполняем prehook
        if self.args.prehook:
            if not self.run_hooks(self.args.prehook, "prehook"):
                print("\n!!! Prehook failed, aborting rebuild")
                sys.exit(1)

        # Коммитим изменения если есть
        committed = False
        if not self.args.no_commit and self.has_changes():
            committed = self.commit_changes(self.args.message)

        # Запускаем rebuild
        rebuild_status = self.run_rebuild()

        # Push если коммит был успешен
        if committed and not self.args.no_push:
            push_done = self.push_changes()
        else:
            push_done = False

        # Выполняем posthook
        if self.args.posthook:
            self.run_hooks(self.args.posthook, "posthook")

        # Итоговый статус
        print(f"\nRebuild: {rebuild_status}")
        if self.args.no_push:
            print("Push: skipped (--no-push)")
        elif not committed:
            print("Push: not made (no commit)")
        else:
            print(f"Push: {'done' if push_done else 'failed'}")

        sys.exit(0 if rebuild_status == "OK" else 1)


def parse_hook_list(hook_string):
    """Разобрать строку хуков в список."""
    if not hook_string:
        return []
    # Разделяем по запятой или пробелу
    hooks = []
    for part in hook_string.replace(",", " ").split():
        hooks.append(part.strip())
    return hooks


def main():
    parser = argparse.ArgumentParser(
        description="Rebuild NixOS конфигурации с поддержкой хуков"
    )
    parser.add_argument(
        "-m", "--message",
        default="rebuild",
        help="Сообщение коммита (по умолчанию: rebuild)"
    )
    parser.add_argument(
        "--prehook",
        type=str,
        default="",
        help="Список функций для выполнения ДО rebuild (через запятую или пробел)"
    )
    parser.add_argument(
        "--posthook",
        type=str,
        default="",
        help="Список функций для выполнения ПОСЛЕ rebuild (через запятую или пробел)"
    )
    parser.add_argument(
        "--no-commit",
        action="store_true",
        help="Не делать коммит"
    )
    parser.add_argument(
        "--no-push",
        action="store_true",
        help="Не делать push"
    )

    args = parser.parse_args()
    args.prehook = parse_hook_list(args.prehook)
    args.posthook = parse_hook_list(args.posthook)

    # Обработка SIGINT (Ctrl+C)
    def signal_handler(signum, frame):
        print("\n!!! Interrupted by user")
        sys.exit(130)

    signal.signal(signal.SIGINT, signal_handler)

    process = RebuildProcess(args)
    process.run()


if __name__ == "__main__":
    main()

